pdfjsLib.GlobalWorkerOptions.workerSrc="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js";const dropZone=document.getElementById("drop-zone"),fileInput=document.getElementById("file-input"),loading=document.getElementById("loading"),scoreSection=document.getElementById("score-section"),resultsGrid=document.getElementById("results-grid"),finalScore=document.getElementById("final-score"),scoreFeedback=document.getElementById("score-feedback");async function processFile(e){dropZone.style.display="none",loading.style.display="block";try{const t=await e.arrayBuffer(),s=await pdfjsLib.getDocument(t).promise;let n="";for(let e=1;e<=s.numPages;e++){const t=await s.getPage(e),o=await t.getTextContent();n+=o.items.map(e=>e.str).join(" ")+"\n"}analyzeResume(n)}catch(e){console.error(e),alert("Error reading PDF. Please ensure it is a valid text-based PDF."),resetAnalyzer()}}function analyzeResume(e){loading.style.display="none",scoreSection.style.display="block",resultsGrid.style.display="grid";const t={score:0,results:[],sections:{contact:/email|phone|address|linkedin|@/i.test(e),summary:/summary|profile|objective|about me/i.test(e),experience:/experience|employment|work history|professional background/i.test(e),education:/education|academic|university|degree|college/i.test(e),skills:/skills|technologies|expertise|competencies/i.test(e)}};let s=20;t.sections.contact&&(t.score+=20,s+=20),t.sections.experience&&(t.score+=20,s+=20),t.sections.education&&(t.score+=20,s+=20),t.sections.skills&&(t.score+=20,s+=20),e.length>500&&(t.score+=10,s+=10),t.score>100&&(t.score=100),finalScore.textContent=Math.min(t.score,100),t.score>=85?scoreFeedback.textContent="Excellent Professional Resume!":t.score>=60?scoreFeedback.textContent="Good Start, but needs improvement.":scoreFeedback.textContent="Your Resume needs significant work.",resultsGrid.innerHTML="";const n=[{title:"Contact Information",passed:t.sections.contact,desc:t.sections.contact?"We found your contact details easily.":"Warning: No email or phone number detected."},{title:"Work Experience",passed:t.sections.experience,desc:t.sections.experience?"Professional history is clearly defined.":"Missing: Explicit 'Experience' section heading."},{title:"Education History",passed:t.sections.education,desc:t.sections.education?"Academic background is present.":"Missing: No 'Education' section found."},{title:"Skills Section",passed:t.sections.skills,desc:t.sections.skills?"Key skills are listed.":"Recommendation: Add a dedicated skills section for ATS."},{title:"Content Density",passed:e.length>800,desc:e.length>800?"Resume has a good amount of detailed content.":"Warning: Your resume seems a bit short. Add more details."}];n.forEach(e=>{const t=document.createElement("div");t.className="result-item "+(e.passed?"passing":"failing"),t.innerHTML=`\n                    <h4>${e.passed?"✅":"🔴"} ${e.title}</h4>\n                    <p>${e.desc}</p>\n                `,resultsGrid.appendChild(t)}),setTimeout(()=>{const e=`Resume Score: ${t.score}\nFeedback: ${scoreFeedback.textContent}\n\n`+n.map(e=>`${e.title}: ${e.passed?"PASS":"FAIL"} - ${e.desc}`).join("\n"),s=new Blob([e],{type:"text/plain"}),o=URL.createObjectURL(s),i=document.createElement("a");i.href=o,i.download="resume_analysis_report.txt",i.click()},1500)}function resetAnalyzer(){dropZone.style.display="block",scoreSection.style.display="none",loading.style.display="none",fileInput.value=""}dropZone.onclick=()=>fileInput.click(),dropZone.ondragover=e=>{e.preventDefault(),dropZone.classList.add("drag-over")},dropZone.ondragleave=()=>dropZone.classList.remove("drag-over"),dropZone.ondrop=e=>{e.preventDefault(),dropZone.classList.remove("drag-over");const t=e.dataTransfer.files[0];t&&"application/pdf"===t.type&&processFile(t)},fileInput.onchange=e=>{const t=e.target.files[0];t&&processFile(t)};